<template>
 <section class="qpa-picker" :aria-label="ct('自定义个人头像')">
  <div class="qpa-picker-head"><AccountAvatar :value="modelValue" :size="52" decorative/><div><span class="qpa-eyebrow">QGAUSS / MAKE IT YOURS</span><h3>{{ct('也可以，更像你。')}}</h3><p>{{ct('放一张喜欢的照片，让创作身份有自己的模样。')}}</p></div><button class="qpa-add" type="button" :disabled="disabled||busy||!!pending||!policy||policy.remaining===0" @click="input?.click()"><ClientIcon name="image"/>{{ct('选一张照片')}}</button></div>
  <input ref="input" class="qpa-file" type="file" accept="image/png,image/jpeg,image/webp,image/gif,image/bmp,.bmp" :aria-label="ct('选择个人头像图片')" :disabled="disabled||busy||!!pending||!policy||policy.remaining===0" @change="choose"/>
  <p class="qpa-hint">{{ct('PNG、JPEG、WebP、GIF、BMP · 最大 12MB')}}<span v-if="policy">{{ct('今天还可准备 {count} 张',{count:policy.remaining})}}</span><button v-else type="button" :disabled="busy" @click="loadPolicy">{{ct('重新读取可用状态')}}</button></p>
  <div v-if="pending" class="qpa-pending" role="status"><span class="qpa-pending-dot"></span><div><b>{{ct('上次的照片，先核对一下。')}}</b><p>{{ct('当前头像不会自动改变，其他资料仍可继续编辑。')}}</p></div><button type="button" :disabled="disabled||busy" @click="recover(false)">{{ct('读取准备结果')}}</button><button type="button" :disabled="disabled||busy" @click="recover(true)">{{ct('放弃这张图片')}}</button></div>
  <p v-if="error" class="qpa-message is-error" role="alert">{{ct(error)}}</p><p v-if="note" class="qpa-message" role="status">{{ct(note)}}</p><button v-if="needsProfileRefresh" class="qpa-read-profile" type="button" :disabled="disabled||busy" @click="$emit('refresh')">{{ct('读取最新个人资料')}} ↗</button>
  <dialog ref="dialog" class="qpa-dialog" aria-labelledby="qpa-title" @cancel.prevent="cancel">
   <header><div><span class="qpa-eyebrow">A LITTLE PORTRAIT. ALL YOU.</span><h2 id="qpa-title">{{ct(mode==='end'?'结束这张照片的准备？':'这一面，就很像你。')}}</h2><p>{{ct(mode==='end'?'先核对这次准备，当前已保存的头像不会被移除。':mode==='ready'?'找到了已准备的照片。确认后放入你的资料预览。':'拖动画面找到主角，缩放到喜欢的位置。')}}</p></div><button class="qpa-close" type="button" :aria-label="ct('关闭头像裁切')" @click="cancel">×</button></header>
   <div class="qpa-dialog-body">
    <div class="qpa-stage"><span class="qpa-stage-glow"></span><div v-if="bitmap&&sourceUrl" ref="viewport" class="qpa-crop" tabindex="0" role="img" :aria-label="ct('头像裁切预览，可拖动或使用方向键调整，Shift 加快移动')" @pointerdown="startDrag" @pointermove="drag" @pointerup="stopDrag" @pointercancel="stopDrag" @keydown="moveKey"><img :src="displaySource" :style="imageStyle" alt="" draggable="false"/><span class="qpa-crop-guides" aria-hidden="true"></span></div><AccountAvatar v-else-if="review?.avatar" :value="review.avatar" :size="220"/><div v-else class="qpa-wait-symbol" aria-hidden="true">✦</div><span class="qpa-stage-caption">YOUR PORTRAIT / YOUR POINT OF VIEW</span><div v-if="busy" class="qpa-working"><BrandLoader :size="32" :text="ct('正在准备这张头像…')"/></div></div>
    <aside class="qpa-controls"><span class="qpa-eyebrow">A FACE FOR EVERY LITTLE IDEA</span><h3>{{ct('在你的空间里，刚刚好。')}}</h3><p>{{ct('方框里的画面会成为头像，原图不会直接公开。')}}</p><div v-if="bitmap" class="qpa-miniatures" aria-hidden="true"><div><span class="qpa-mini-image"><img :src="displaySource" :style="imageStyle" alt=""/></span><small>{{ct('个人空间')}}</small></div><div><span class="qpa-mini-image is-small"><img :src="displaySource" :style="imageStyle" alt=""/></span><small>{{ct('账户入口')}}</small></div></div><template v-if="bitmap"><label for="qpa-zoom">{{ct('靠近一点')}} <output>{{Number(zoom).toFixed(1)}}×</output></label><input id="qpa-zoom" v-model.number="zoom" type="range" min="1" max="4" step="0.05" :aria-label="ct('头像图片缩放')" :disabled="busy||!!intent"/><button class="qpa-reset" type="button" :disabled="busy||!!intent" @click="resetCrop">{{ct('回到正中')}} ↺</button><small>{{ct('方向键可微调位置，按住 Shift 移动更快。')}}</small></template><p v-if="mode==='end'" class="qpa-end-note">{{ct(review?.current?'这张图片已用于当前头像，结束等待不会撤销已保存的资料。':review?.status==='ready'?'图片已准备好，但尚未用于头像。放弃后不会自动保存到资料。':'结束后，迟到的准备结果也不会替换当前头像。')}}</p><p v-if="error" class="qpa-message is-error" role="alert">{{ct(error)}}</p></aside>
   </div>
   <footer><p>{{ct('先放入预览，再保存创作身份。昵称和签名会一起保留。')}}</p><div><button type="button" @click="cancel">{{ct(busy?'暂时返回':'返回编辑')}}</button><button class="qpa-primary" type="button" :disabled="busy||disabled||mode==='crop'&&!bitmap" @click="confirm">{{ct(busy?'正在准备…':mode==='end'?'确认结束这次准备':mode==='ready'?'使用已准备的图片':'放入头像预览')}} <ClientIcon name="arrowUpRight"/></button></div></footer>
  </dialog>
 </section>
</template>
<script setup>
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue';
import {api,uploadProfileAvatar} from '../../api/client.js';
import {useAuth} from '../../stores/auth.js';
import {currentLang} from '../../i18n/index.js';
import {useMotionPreference} from '../../composables/useMotionPreference.js';
import {accountText} from '../../i18n/account-messages.js';
import {avatarCrop,avatarFileProblem,avatarReceipt,avatarImageId} from '../../lib/profile-avatar.js';
import {readAvatarPending,saveAvatarPending} from '../../lib/avatar-pending.js';
import AccountAvatar from './AccountAvatar.vue';import BrandLoader from './BrandLoader.vue';import ClientIcon from '../reference/ClientIcon.vue';import './profile-photo.css';
const props=defineProps({modelValue:String,disabled:Boolean}),emit=defineEmits(['update:modelValue','busy','editing','refresh']),auth=useAuth(),ct=(key,params)=>accountText(currentLang.value,key,params),input=ref(null),dialog=ref(null),viewport=ref(null),bitmap=ref(null),sourceUrl=ref(''),posterUrl=ref(''),quiet=useMotionPreference(),displaySource=computed(()=>quiet.value?posterUrl.value:sourceUrl.value),zoom=ref(1),cx=ref(.5),cy=ref(.5),busy=ref(false),pending=ref(null),policy=ref(null),error=ref(''),note=ref(''),mode=ref('crop'),review=ref(null),needsProfileRefresh=ref(false),intent=ref(null);
let source,controller,epoch=0,alive=true,dragging,policyController,policyVersion=0,editing=false;
const stamp=()=>({id:auth.user?.id,revision:auth.identityRevision}),current=owner=>alive&&auth.isLoggedIn&&owner.id===auth.user?.id&&owner.revision===auth.identityRevision;
const crop=computed(()=>bitmap.value?avatarCrop(bitmap.value.width,bitmap.value.height,Number(zoom.value),cx.value,cy.value):null),imageStyle=computed(()=>crop.value?{width:crop.value.width/crop.value.size*100+'%',height:crop.value.height/crop.value.size*100+'%',left:-crop.value.x/crop.value.size*100+'%',top:-crop.value.y/crop.value.size*100+'%'}:{});
function setBusy(value){busy.value=value;emit('busy',value);}function setEditing(value){editing=value;emit('editing',value);}function remember(row){pending.value=row;saveAvatarPending(auth.user?.id,row);}function release(){bitmap.value?.close?.();bitmap.value=null;source=null;intent.value=null;dragging=null;if(sourceUrl.value)URL.revokeObjectURL(sourceUrl.value);sourceUrl.value='';if(posterUrl.value)URL.revokeObjectURL(posterUrl.value);posterUrl.value='';}
function cancel(){epoch++;controller?.abort();controller=null;setBusy(false);dialog.value?.close();setEditing(false);release();review.value=null;if(pending.value)note.value='这张照片的准备结果仍保留，可稍后继续核对。';}
function resetCrop(){zoom.value=1;cx.value=.5;cy.value=.5;}
async function loadPolicy(){const owner=stamp(),version=++policyVersion;policyController?.abort();const request=new AbortController();policyController=request;try{const row=await api.get('/users/me/avatar/policy',{signal:request.signal,retry:false});if(!current(owner)||request.signal.aborted||version!==policyVersion)return;if(!row||!Number.isSafeInteger(row.remaining)||row.remaining<0||row.remaining>row.dailyLimit||row.maxBytes!==12*1024*1024||row.dailyLimit!==10)throw Error('暂时无法确认头像准备状态，请重新读取。');policy.value=row;}catch(e){if(current(owner)&&!request.signal.aborted&&version===policyVersion){policy.value=null;error.value=e.message||'暂时无法确认头像准备状态，请重新读取。';}}}
async function choose(event){const file=event.target.files?.[0];event.target.value='';if(!file||props.disabled||busy.value||pending.value||!policy.value)return;error.value='';note.value='';needsProfileRefresh.value=false;const problem=avatarFileProblem(file);if(problem){error.value=problem;return;}const owner=stamp(),at=++epoch;release();setBusy(true);let image;try{image=await createImageBitmap(file,{imageOrientation:'from-image'});if(!current(owner)||at!==epoch){image.close();return;}avatarCrop(image.width,image.height);bitmap.value=image;source=file;sourceUrl.value=URL.createObjectURL(file);const poster=document.createElement('canvas'),ratio=Math.min(1,1536/Math.max(image.width,image.height));poster.width=Math.max(1,Math.round(image.width*ratio));poster.height=Math.max(1,Math.round(image.height*ratio));poster.getContext('2d').drawImage(image,0,0,poster.width,poster.height);const still=await new Promise(resolve=>poster.toBlob(resolve,'image/png'));if(!current(owner)||at!==epoch)return;if(!still)throw Error();posterUrl.value=URL.createObjectURL(still);resetCrop();mode.value='crop';setEditing(true);await nextTick();dialog.value?.showModal();viewport.value?.focus();}catch(e){image?.close?.();if(current(owner)&&at===epoch){release();error.value=e.message==='图片像素过大，请使用不超过 6400 万像素的图片。'?e.message:'图片无法完整读取，请换一张图片。';}}finally{if(current(owner)&&at===epoch)setBusy(false);}}
function startDrag(event){if(busy.value||intent.value||!crop.value)return;const c=crop.value;cx.value=(c.x+c.size/2)/c.width;cy.value=(c.y+c.size/2)/c.height;dragging={x:event.clientX,y:event.clientY,cx:cx.value,cy:cy.value,crop:c,width:viewport.value.getBoundingClientRect().width};viewport.value.setPointerCapture?.(event.pointerId);}
function drag(event){if(!dragging||busy.value||intent.value)return;const d=dragging;cx.value=Math.max(0,Math.min(1,d.cx-(event.clientX-d.x)*d.crop.size/d.width/d.crop.width));cy.value=Math.max(0,Math.min(1,d.cy-(event.clientY-d.y)*d.crop.size/d.width/d.crop.height));}function stopDrag(){dragging=null;}
function moveKey(event){if(busy.value||intent.value||!crop.value||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();const c=crop.value,step=Math.max(1,Math.round(c.size/100))*(event.shiftKey?10:1);cx.value=(c.x+c.size/2+(event.key==='ArrowLeft'?-step:event.key==='ArrowRight'?step:0))/c.width;cy.value=(c.y+c.size/2+(event.key==='ArrowUp'?-step:event.key==='ArrowDown'?step:0))/c.height;}
function newKey(){if(crypto.randomUUID)return crypto.randomUUID();const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=bytes[6]&15|64;bytes[8]=bytes[8]&63|128;const h=Array.from(bytes,n=>n.toString(16).padStart(2,'0')).join('');return[h.slice(0,8),h.slice(8,12),h.slice(12,16),h.slice(16,20),h.slice(20)].join('-');}
async function preparedInput(){const c={...crop.value};if(!/^(?:image\/bmp|image\/x-ms-bmp)$/i.test(source.type)&&!(/\.bmp$/i.test(source.name)&&!source.type))return{file:source,crop:c};const canvas=document.createElement('canvas');canvas.width=512;canvas.height=512;canvas.getContext('2d').drawImage(bitmap.value,c.x,c.y,c.size,c.size,0,0,512,512);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('这张图片暂时无法准备，请重新选择。');return{file:new File([blob],'QGauss-avatar.png',{type:'image/png'}),crop:{x:0,y:0,size:512,width:512,height:512}};}
function applyReady(row){emit('update:modelValue',row.avatar);remember(null);cancel();note.value='头像已加入预览，保存创作身份后生效。';void loadPolicy();}
async function waitReady(row,owner,at){const key=pending.value?.key;for(let i=0;i<60&&row.status==='processing';i++){await new Promise(resolve=>setTimeout(resolve,750));if(!current(owner)||at!==epoch)return null;row=await api.get('/users/me/avatar/uploads/'+key,{signal:controller.signal,retry:false});if(!avatarReceipt(row,key))throw Error('头像准备结果不完整，请核对原结果。');remember({...pending.value,operationVersion:row.version});}return row;}
async function confirm(){if(busy.value||props.disabled)return;if(mode.value==='ready'){applyReady(review.value);return;}if(mode.value==='end'){await finishEnding();return;}if(!bitmap.value||!source)return;const owner=stamp(),at=++epoch;controller=new AbortController();setBusy(true);error.value='';try{if(!intent.value){const body=await preparedInput();if(!current(owner)||at!==epoch)return;intent.value={...body,key:newKey()};remember({key:intent.value.key,operationVersion:0});}const body=intent.value;let row=await uploadProfileAvatar(body.file,body.key,body.crop,pending.value.operationVersion,{signal:controller.signal});if(!current(owner)||at!==epoch)return;if(!avatarReceipt(row,body.key))throw Error('头像准备结果不完整，请核对原结果。');remember({...pending.value,operationVersion:row.version});row=await waitReady(row,owner,at);if(!row||!current(owner)||at!==epoch)return;if(row.status==='ready')applyReady(row);else if(row.status==='closed'){remember(null);cancel();note.value='这次头像准备已经结束，原头像保持不变。';}else if(row.status==='failed'){error.value=row.error||'这张图片尚未准备好，请重新核对后再试。';cancel();}else{cancel();note.value='头像仍在准备，可以稍后读取结果。';}}catch(e){if(current(owner)&&at===epoch){error.value=e.message||'头像准备结果尚未确认，请读取原结果。';cancel();}}finally{if(current(owner)&&at===epoch)setBusy(false);void loadPolicy();}}
async function recover(ending){if(!pending.value||busy.value||props.disabled)return;const owner=stamp(),at=++epoch,key=pending.value.key;controller=new AbortController();setBusy(true);error.value='';review.value=null;try{let row;try{row=await api.get('/users/me/avatar/uploads/'+key,{signal:controller.signal,retry:false});}catch(e){if(e.status!==404||!ending)throw e;row={requestKey:key,version:0,status:'missing'};}if(!current(owner)||at!==epoch)return;if(row.status!=='missing'&&!avatarReceipt(row,key))throw Error('头像准备结果不完整，请核对原结果。');if(row.status==='closed'){remember(null);note.value='这次头像准备已经结束，原头像保持不变。';return;}remember({...pending.value,operationVersion:row.version});review.value=row;if(!ending&&row.status!=='ready'){note.value=row.error||'头像仍在准备，可以稍后读取结果。';return;}release();mode.value=ending?'end':'ready';setEditing(true);await nextTick();dialog.value?.showModal();}catch(e){if(current(owner)&&at===epoch)error.value=e.status===404?'暂未找到这次准备，可稍后核对或明确结束等待。':e.message;}finally{if(current(owner)&&at===epoch)setBusy(false);}}
async function finishEnding(){const owner=stamp(),at=++epoch,key=pending.value?.key;if(!key||!review.value)return;controller=new AbortController();setBusy(true);error.value='';try{const row=await api.post('/users/me/avatar/uploads/'+key+'/close',{expectedVersion:review.value.version},{signal:controller.signal,retry:false});if(!current(owner)||at!==epoch)return;if(!avatarReceipt(row,key)||!['closed','ready'].includes(row.status))throw Error('暂未确认准备是否已结束，请重新读取。');remember(null);needsProfileRefresh.value=!!row.current;cancel();note.value=row.current?'这张图片已在其他页面保存，读取最新资料即可查看。':'这次头像准备已结束，原头像和其他资料保持不变。';void loadPolicy();}catch(e){if(current(owner)&&at===epoch){error.value=e.status===409?'这次准备已有变化，请读取最新结果后再决定。':e.message||'暂未确认准备是否已结束，请重新读取。';cancel();}}finally{if(current(owner)&&at===epoch)setBusy(false);}}
function beforeUnload(event){if(editing&&!pending.value){event.preventDefault();event.returnValue='';}}
watch([()=>auth.user?.id,()=>auth.identityRevision],()=>{cancel();policyController?.abort();error.value='';note.value='';needsProfileRefresh.value=false;policy.value=null;pending.value=auth.isLoggedIn?readAvatarPending(auth.user.id):null;if(auth.isLoggedIn)void loadPolicy();},{immediate:true});
watch([()=>auth.user?.avatar,()=>props.modelValue],([saved,value])=>{if(note.value==='头像已加入预览，保存创作身份后生效。'&&(saved===value||!avatarImageId(value)))note.value='';});
window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>{alive=false;cancel();policyController?.abort();window.removeEventListener('beforeunload',beforeUnload);});
</script>
